select `ni`.`nin_id_planilla` AS `nin_id_planilla`,`p`.`ppl_numero` AS `planilla`,`p`.`ppl_estado_proceso` AS `estado_planilla`,`e`.`emp_correlativo` AS `id_empleado`,`e`.`emp_dpi` AS `emp_dpi`,concat(`e`.`emp_nombres`,' ',`e`.`emp_apellidos`) AS `nombre_completo`,`e`.`emp_fecha_ingreso` AS `emp_fecha_ingreso`,`e`.`emp_profesion_oficio` AS `puesto`,`ni`.`nin_dias_trabajados` AS `dias_trabajados`,sum(`ni`.`nin_valor`) AS `total_ingresos`,coalesce((select sum(`apps_rpjepq`.`rpj_prc_nomina_descuento`.`nde_valor`) from `apps_rpjepq`.`rpj_prc_nomina_descuento` where `apps_rpjepq`.`rpj_prc_nomina_descuento`.`nde_id_planilla` = `ni`.`nin_id_planilla` and `apps_rpjepq`.`rpj_prc_nomina_descuento`.`nde_id_empleado` = `ni`.`nin_id_empleado`),0) AS `total_descuentos`,sum(`ni`.`nin_valor`) - coalesce((select sum(`apps_rpjepq`.`rpj_prc_nomina_descuento`.`nde_valor`) from `apps_rpjepq`.`rpj_prc_nomina_descuento` where `apps_rpjepq`.`rpj_prc_nomina_descuento`.`nde_id_planilla` = `ni`.`nin_id_planilla` and `apps_rpjepq`.`rpj_prc_nomina_descuento`.`nde_id_empleado` = `ni`.`nin_id_empleado`),0) AS `neto_a_pagar` from ((`apps_rpjepq`.`rpj_prc_nomina_ingreso` `ni` join `apps_rpjepq`.`rpj_cat_parametro_planilla` `p` on(`p`.`ppl_correlativo` = `ni`.`nin_id_planilla`)) join `apps_rpjepq`.`rpj_mnt_empleado` `e` on(`e`.`emp_correlativo` = `ni`.`nin_id_empleado`)) where `ni`.`nin_tipo_manejo` = 1 group by `ni`.`nin_id_planilla`,`p`.`ppl_numero`,`p`.`ppl_estado_proceso`,`e`.`emp_correlativo`,`e`.`emp_dpi`,`e`.`emp_nombres`,`e`.`emp_apellidos`,`e`.`emp_fecha_ingreso`,`e`.`emp_profesion_oficio`,`ni`.`nin_dias_trabajados`
